def count_triples(S_subset, n):
    """Counts triples (x, y, z) in S_subset^3 such that x+y+z is divisible by n."""
    count = 0
    for x in S_subset:
        for y in S_subset:
            for z in S_subset:
                if (x + y + z) % n == 0:
                    count += 1
    return count

def test_coloring(n):
    S = list(range(1, n + 1))

    # Coloring 1: Parity (Odd=Red, Even=Blue)
    R_parity = [x for x in S if x % 2 != 0]
    B_parity = [x for x in S if x % 2 == 0]

    C_R_parity = count_triples(R_parity, n)
    C_B_parity = count_triples(B_parity, n)

    total_parity = C_R_parity + C_B_parity

    return total_parity

# Test n from 1 to 15
results = {}
for n in range(1, 16):
    results[n] = test_coloring(n)

print("n | Total Triples (Parity Coloring)")
print("---|---------------------------------")
for n, total in results.items():
    print(f"{n} | {total}")

